    let n: usize = b.len();
    let l: usize = if m >= n { m } else { n };

    // Precondition implies both non-empty, so when m==1 or n==1 we can safely read index 0.
    if m == n {
        // Exact-copy case, satisfies the strong postcondition directly.
        return (a, b);
    }

    let mut out_a: Vec<i8> = Vec::with_capacity(l);
    let mut out_b: Vec<i8> = Vec::with_capacity(l);

